import random
import string

import pytest

from solution import decode_cyclic


def _reference_encode(s: str) -> str:
    groups = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    groups = [(g[1:] + g[0]) if len(g) == 3 else g for g in groups]
    return "".join(groups)


def test_empty_string():
    """REQ: R1, R2
    Empty encoded string decodes to empty string."""
    assert decode_cyclic("") == ""


@pytest.mark.parametrize("s", ["a", "ab"])
def test_short_strings_unchanged(s):
    """REQ: R1, R2
    Strings shorter than 3 are not cycled by the encoder, so decode returns them unchanged."""
    assert decode_cyclic(s) == s


def test_single_full_group():
    """REQ: R1, R2"""
    assert decode_cyclic("bca") == "abc"


def test_two_full_groups():
    """REQ: R1, R2"""
    assert decode_cyclic("bcaefd") == "abcdef"


def test_full_group_plus_one():
    """REQ: R1, R2"""
    assert decode_cyclic("bcad") == "abcd"


def test_full_group_plus_two():
    """REQ: R1, R2"""
    assert decode_cyclic("bcade") == "abcde"


def test_seven_chars():
    """REQ: R1, R2"""
    assert decode_cyclic("bcaefdg") == "abcdefg"


def test_eight_chars():
    """REQ: R1, R2"""
    assert decode_cyclic("bcaefdgh") == "abcdefgh"


def test_nine_chars():
    """REQ: R1, R2"""
    assert decode_cyclic("bcaefdhig") == "abcdefghi"


def test_hello_world():
    """REQ: R1, R2"""
    assert decode_cyclic("elho lorwld") == "hello world"


def test_repeated_characters():
    """REQ: R1, R2"""
    assert decode_cyclic("aaaaaa") == "aaaaaa"


@pytest.mark.parametrize("length", list(range(0, 31)))
def test_round_trip_various_lengths(length):
    """REQ: R1, R2
    Decoding an encoded string of any length restores the original."""
    rng = random.Random(1000 + length)
    original = "".join(rng.choice(string.ascii_letters + string.digits + " !?") for _ in range(length))
    assert decode_cyclic(_reference_encode(original)) == original


def test_round_trip_random_seeded():
    """REQ: R1, R2"""
    rng = random.Random(42)
    for _ in range(100):
        n = rng.randint(0, 50)
        original = "".join(rng.choice(string.ascii_lowercase) for _ in range(n))
        assert decode_cyclic(_reference_encode(original)) == original


def test_unicode_round_trip():
    """REQ: R1, R2"""
    original = "héllo wörld ☃✓"
    assert decode_cyclic(_reference_encode(original)) == original

