from solution import fib4


def _reference(n):
    seq = [0, 0, 2, 0]
    if n < 4:
        return seq[n]
    for _ in range(4, n + 1):
        seq = [seq[1], seq[2], seq[3], sum(seq)]
    return seq[3]


