def _reference(n):
    a, b, c, d = 0, 0, 2, 0
    if n == 0:
        return a
    if n == 1:
        return b
    if n == 2:
        return c
    if n == 3:
        return d
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d


