    n = 200
    result = {}

    def run():
        try:
            result["value"] = fibfib(n)
        except BaseException as exc:  # pragma: no cover
            result["error"] = exc

    t = threading.Thread(target=run, daemon=True)
    t.start()
    t.join(timeout=5)
