import pytest

from solution import is_multiply_prime


def _reference(n):
    """Count prime factors with multiplicity by trial division."""
    if n <= 1:
        return False
    count = 0
    d = 2
    m = n
    while d * d <= m:
        while m % d == 0:
            m //= d
            count += 1
        d += 1
    if m > 1:
        count += 1
    return count == 3


