def _reference_prime_factor_count(n):
    """Count prime factors of n with multiplicity (independent oracle)."""
    count = 0
    d = 2
    while d * d <= n:
        while n % d == 0:
            n //= d
            count += 1
        d += 1
    if n > 1:
        count += 1
    return count


