from solution import starts_one_ends


def _brute(n):
    lo = 10 ** (n - 1)
    hi = 10 ** n
    count = 0
    for x in range(lo, hi):
        s = str(x)
        if s[0] == "1" or s[-1] == "1":
            count += 1
    return count


def test_n_equals_one():
    """REQ: R1
    Only the single-digit number 1 starts or ends with 1."""
    assert starts_one_ends(1) == 1


def test_n_equals_two():
    """REQ: R1
    10..19 start with 1 (10), 21..91 end with 1 (8 more) -> 18."""
    assert starts_one_ends(2) == 18


def test_n_equals_three():
    """REQ: R1"""
    assert starts_one_ends(3) == 180


def test_n_equals_four():
    """REQ: R1"""
    assert starts_one_ends(4) == 1800


def test_n_equals_five():
    """REQ: R1"""
    assert starts_one_ends(5) == 18000


def test_matches_brute_force_small_n():
    """REQ: R1
    Cross-check against exhaustive enumeration for small n."""
    for n in range(1, 6):
        assert starts_one_ends(n) == _brute(n)


def test_large_n_formula():
    """REQ: R1
    For n >= 2: 10^(n-1) start with 1, plus 8*10^(n-2) end with 1 but don't start with 1."""
    for n in (6, 10, 20):
        assert starts_one_ends(n) == 18 * 10 ** (n - 2)

