import sys

import pytest

from solution import fib4


def _reference(n):
    vals = [0, 0, 2, 0]
    if n < 4:
        return vals[n]
    a, b, c, d = vals
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d


def test_base_case_zero():
    """REQ: E1"""
    assert fib4(0) == 0


def test_base_case_one():
    """REQ: E2"""
    assert fib4(1) == 0


def test_base_case_two():
    """REQ: E3"""
    assert fib4(2) == 2


def test_base_case_three():
    """REQ: E4"""
    assert fib4(3) == 0


def test_fib4_five():
    """REQ: E6"""
    assert fib4(5) == 4


def test_fib4_six():
    """REQ: E7"""
    assert fib4(6) == 8


def test_fib4_seven():
    """REQ: E8"""
    assert fib4(7) == 14


def test_first_four_terms_of_recurrence():
    """REQ: E5, R1"""
    assert fib4(4) == 2


@pytest.mark.parametrize(
    "n,expected",
    [(4, 2), (5, 4), (6, 8), (7, 14), (8, 28), (9, 54), (10, 104), (11, 200), (12, 386)],
)
def test_known_values(n, expected):
    """REQ: R1, E5"""
    assert fib4(n) == expected


def test_full_initial_sequence():
    """REQ: R1, E1, E2, E3, E4, E5"""
    assert [fib4(i) for i in range(13)] == [0, 0, 2, 0, 2, 4, 8, 14, 28, 54, 104, 200, 386]


@pytest.mark.parametrize("n", range(4, 60))
def test_recurrence_relation_holds(n):
    """REQ: E5"""
    assert fib4(n) == fib4(n - 1) + fib4(n - 2) + fib4(n - 3) + fib4(n - 4)


def test_matches_reference_for_larger_n():
    """REQ: R1, E5"""
    for n in (20, 50, 100, 250):
        assert fib4(n) == _reference(n)


def test_returns_int():
    """REQ: R1"""
    assert isinstance(fib4(10), int)
    assert isinstance(fib4(0), int)


def test_large_n_efficient_and_exact():
    """REQ: R1, R2"""
    n = 5000
    assert fib4(n) == _reference(n)


def test_no_recursion_with_low_recursion_limit():
    """REQ: R2"""
    old = sys.getrecursionlimit()
    try:
        sys.setrecursionlimit(200)
        result = fib4(1000)
    finally:
        sys.setrecursionlimit(old)
    assert result == _reference(1000)

