    assert iscube(a) is False


def test_squares_that_are_not_cubes():
    """REQ: R1"""
    for a in [4, 9, 16, 25, 36, 49, 81, 100, 144]:
        assert iscube(a) is False


def test_sixth_powers_are_cubes():
    """REQ: R1"""
    for k in range(1, 8):
        assert iscube(k ** 6) is True


def test_larger_cubes_and_neighbours():
    """REQ: R1"""
    for n in [100, 999, 1000, 9999]:
        c = n ** 3
        assert iscube(c) is True
        assert iscube(-c) is True
        assert iscube(c + 1) is False
        assert iscube(c - 1) is False


def test_neighbours_of_small_cubes_are_not_cubes():
    """REQ: R1"""
    for n in range(2, 20):
        c = n ** 3
        assert iscube(c + 1) is False
        assert iscube(c - 1) is False


def test_returns_bool_for_valid_integer_inputs():
    """REQ: R2"""
    for a in [0, 1, -1, 2, 64, 180, -8, 1000]:
        assert isinstance(iscube(a), bool)


def test_deterministic_repeated_calls():
    """REQ: R2, R1"""
    for _ in range(3):
        assert iscube(27) is True
        assert iscube(28) is False

import pytest
from solution import starts_one_ends


def _brute(n):
    lo = 10 ** (n - 1) if n > 1 else 1
    hi = 10 ** n
    return sum(1 for x in range(lo, hi) if str(x)[0] == "1" or str(x)[-1] == "1")


def test_n_equals_one():
    """REQ: R1
    Single-digit positive integers: only 1 starts or ends with 1."""
    assert starts_one_ends(1) == 1


def test_n_equals_two():
    """REQ: R1
    10..19 (10 numbers) plus 21,31,...,91 (8 more) = 18."""
    assert starts_one_ends(2) == 18


def test_n_equals_three():
    """REQ: R1
    100 starting with 1 + 90 ending with 1 - 10 both = 180."""
    assert starts_one_ends(3) == 180


def test_n_equals_four():
    """REQ: R1"""
    assert starts_one_ends(4) == 1800


def test_n_equals_five():
    """REQ: R1"""
    assert starts_one_ends(5) == 18000


@pytest.mark.parametrize("n", [1, 2, 3, 4, 5])
def test_matches_brute_force(n):
    """REQ: R1
    Compare against direct enumeration for small n."""
    assert starts_one_ends(n) == _brute(n)


@pytest.mark.parametrize("n", [6, 10, 15, 20])
def test_larger_values_formula(n):
    """REQ: R1
    Inclusion-exclusion: 10^(n-1) + 9*10^(n-2) - 10^(n-2) = 18*10^(n-2)."""
    assert starts_one_ends(n) == 18 * 10 ** (n - 2)


def test_returns_integer():
    """REQ: R1"""
    result = starts_one_ends(3)
    assert isinstance(result, int)
    assert result == 180

